import{_ as r,o as s,c as o,a2 as e}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"故障排查","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/troubleshooting.md","filePath":"zh-HK/user-guide/troubleshooting.md","lastUpdated":1787586465000}'),a={name:"zh-HK/user-guide/troubleshooting.md"};function n(i,t,l,g,h,d){return s(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>在使用 Lertaro 的過程中遇到問題？請按照以下步驟逐步排查常見故障原因。</p><h2 id="_1-全域熱鍵沒有反應" tabindex="-1">1. 全域熱鍵沒有反應 <a class="header-anchor" href="#_1-全域熱鍵沒有反應" aria-label="Permalink to &quot;1. 全域熱鍵沒有反應&quot;">​</a></h2><ul><li><strong>檢查後台服務運行狀態</strong>：進入<a href="./settings/service-status.html"><strong>設定 → 運行狀態</strong></a>，確認 <code>Lertaro.Service</code> 處於「運行中」。雖然普通熱鍵由 App 處理，但提權攔截程序依賴後台服務拉起。</li><li><strong>系統管理員權限隔離（UIPI）</strong>：若當前前景活動視窗是以系統管理員身分運行的（例如以系統管理員開啟的終端機或工作管理員），Windows 系統的安全機制（UIPI）會阻止低權限程序向高權限視窗傳送熱鍵。Lertaro 會自動嘗試提權熱鍵攔截程序；若仍無回應，請確保後台服務處於正常運行狀態。</li><li><strong>檢查程序黑名單</strong>：在<a href="./settings/hotkeys-page.html#process-blacklist"><strong>設定 → 熱鍵</strong></a>中檢查當前前景程式是否被列入了「程序黑名單」。處於黑名單中的程式在前景時，Lertaro 會主動放行按鍵不做攔截。</li><li><strong>全螢幕遊戲/獨占應用程式放行</strong>：當偵測到前景有獨占全螢幕應用程式（如 3D 遊戲、全螢幕播放器）時，Lertaro 預設會自動放行熱鍵以防干擾操作。如果你希望在全螢幕下依然能夠呼出搜尋框，請在<strong>設定 → 熱鍵</strong>中勾選<strong>全螢幕應用程式聚焦時仍然回應</strong>。</li></ul><h2 id="_2-搜尋結果未更新或過時" tabindex="-1">2. 搜尋結果未更新或過時 <a class="header-anchor" href="#_2-搜尋結果未更新或過時" aria-label="Permalink to &quot;2. 搜尋結果未更新或過時&quot;">​</a></h2><ul><li><strong>本機 NTFS / ReFS 磁碟</strong>：Lertaro 透過讀取底層 USN 變更記錄檔實現近乎零延遲的毫秒級即時更新。</li><li><strong>FAT32 / exFAT 磁碟</strong>：透過系統檔案變更事件持續監聽。</li><li><strong>手動重建索引</strong>：若由於系統意外斷電等原因導致索引不一致，請前往<a href="./settings/index-drives.html"><strong>設定 → 索引 → 本機磁碟機</strong></a>，在對應的磁碟上按一下<strong>重建索引</strong>即可重新產生乾淨的記憶體索引。</li></ul><h2 id="_3-網路磁碟機未自動重新整理" tabindex="-1">3. 網路磁碟機未自動重新整理 <a class="header-anchor" href="#_3-網路磁碟機未自動重新整理" aria-label="Permalink to &quot;3. 網路磁碟機未自動重新整理&quot;">​</a></h2><ul><li><strong>定時掃描機制</strong>：網路共用（SMB / NAS）沒有本機 NTFS 卷的底層變更記錄檔，因此依賴定時輪詢機制。</li><li><strong>檢查重新整理模式</strong>：在<a href="./settings/index-drives.html#network-drives"><strong>設定 → 索引 → 網路磁碟機</strong></a>中檢查該磁碟機的重新整理模式是否被誤設為了「手動」；若設為手動，必須按一下「重建索引」或改為定時重新整理。</li><li><strong>符號連結環路保護</strong>：對於 NAS 共用中可能存在的遞迴符號連結，Lertaro 內建了環路偵測引擎，會自動略過死循環目錄。</li></ul><h2 id="_4-某個檔案或資料夾完全搜尋不到" tabindex="-1">4. 某個檔案或資料夾完全搜尋不到 <a class="header-anchor" href="#_4-某個檔案或資料夾完全搜尋不到" aria-label="Permalink to &quot;4. 某個檔案或資料夾完全搜尋不到&quot;">​</a></h2><ul><li><strong>檢查排除規則</strong>：進入<a href="./settings/index-drives.html#exclusion-rules"><strong>設定 → 索引 → 排除規則</strong></a>，確認目標檔案路徑是否被精確路徑、Glob 萬用字元或規則運算式規則意外命中。</li><li><strong>檢查磁碟啟用狀態</strong>：在<a href="./settings/index-drives.html"><strong>設定 → 索引 → 本機磁碟機</strong></a>中確認該檔案所在的實體磁碟機或目錄是否處於開啟狀態。</li></ul><h2 id="_5-內嵌視窗中中文輸入法候選字浮窗未彈出" tabindex="-1">5. 內嵌視窗中中文輸入法候選字浮窗未彈出 <a class="header-anchor" href="#_5-內嵌視窗中中文輸入法候選字浮窗未彈出" aria-label="Permalink to &quot;5. 內嵌視窗中中文輸入法候選字浮窗未彈出&quot;">​</a></h2><ul><li><strong>無焦點設計原理</strong>：<a href="./getting-started.html#3-三種視窗形態">內嵌視窗</a>為了在關閉後無縫將焦點歸還給宿主軟體，特意採用了非侵入式無焦點設計。輸入法候選字浮窗依賴 Windows 真實鍵盤焦點，因此在內聯視窗中可能不顯示候選浮窗。</li><li><strong>推薦解決方案</strong>： <ol><li><strong>直接打拼音</strong>：Lertaro 內建了強大的拼音別名引擎，直接輸入拼音字母即可跳躍命中中文檔案名稱（詳見<a href="./search-syntax.html#8-多語言與拼音別名"><strong>搜尋語法</strong></a>），無需調用輸入法候選字浮窗。</li><li><strong>切換為快速視窗</strong>：按下雙擊 <code>Ctrl</code> 喚出擁有完整焦點的快速視窗，即可正常使用任何輸入法。</li></ol></li></ul><h2 id="_6-記錄檢視與提交-issue" tabindex="-1">6. 記錄檢視與提交 Issue <a class="header-anchor" href="#_6-記錄檢視與提交-issue" aria-label="Permalink to &quot;6. 記錄檢視與提交 Issue&quot;">​</a></h2><p>若上述步驟均未能解決你的問題，請進入<a href="./settings/service-status.html"><strong>設定 → 運行狀態</strong></a>檢視詳細的運行記錄：</p><ul><li><strong>Service 記錄</strong>：記錄後台索引服務、USN 記錄檔讀取、網路磁碟掃描與 IPC 通訊狀態。</li><li><strong>App 記錄</strong>：記錄前台 UI 渲染、外掛模組載入、快捷鍵回應與設定變動。</li><li><strong>Hook 記錄</strong>：記錄全域鍵盤鉤子與滑鼠導覽手勢的事件串流。</li></ul><p>你可以在記錄面板中使用搜尋框過濾關鍵字，或按記錄等級（Info / Warn / Error）快速定位異常堆疊，並在 GitHub 提交 Issue 時附上相關記錄以便快速定位。</p>',16)])])}const _=r(a,[["render",n]]);export{c as __pageData,_ as default};
